<?php require_once "config/database.php";require_once "includes/functions.php";$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){try{$st=$pdo->prepare("INSERT INTO users(name,email,phone,password_hash,role) VALUES(?,?,?,?, 'customer')");$st->execute([trim($_POST["name"]),trim($_POST["email"]),trim($_POST["phone"]),password_hash($_POST["password"],PASSWORD_DEFAULT)]);header("Location: login.php");exit;}catch(Exception $e){$error="Could not register. Email may already exist.";}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | JKtech.lk</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/navbar.php";?><main class="auth-wrap"><form class="auth-card" method="post"><span class="eyebrow">JOIN JKTECH</span><h1>Create account.</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Password<input type="password" name="password" minlength="6" required></label><button class="btn primary">Register</button></form></main></body></html>